    def on(self, event: str, callback: Callable) -> None:
        self._callbacks[event].append(callback)

    def get_metrics(self) -> Dict[str, float]:
        return dict(self._metrics)

    def get_history(self, last_n: int = 100) -> List[Dict]:
        return list(self._history)[-last_n:]

    def reset(self) -> None:
        with self._lock:
            self._step = 0
            self._history.clear()
            self._metrics.clear()
            self._cache.clear()

    def save_state(self, path: str) -> None:
        state = {"step": self._step, "metrics": self._metrics, "config": self.config.to_dict()}
        with open(path, "w") as f: json.dump(state, f, indent=2)

    def load_state(self, path: str) -> None:
        with open(path, "r") as f: state = json.load(f)
        self._step = state.get("step", 0)
        self._metrics = state.get("metrics", {})

    def __repr__(self) -> str:
        return f"anchor_optimizerComponent16(step={self._step}, metrics={len(self._metrics)})"

